import{f as e,o as a,c as o,a2 as d}from"./chunks/framework.Cd9rfTEn.js";const E=JSON.parse('{"title":"Casos de prueba de aceptación — M11 VEN — Ventas, presupuestos y punto de venta","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/M11-VEN-ventas-presupuestos.md","filePath":"entregables-analisis-diseno/20-casos-prueba/M11-VEN-ventas-presupuestos.md","lastUpdated":null}'),n={name:"entregables-analisis-diseno/20-casos-prueba/M11-VEN-ventas-presupuestos.md"};function i(r,t,c,s,l,u){return a(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="casos-de-prueba-de-aceptacion-—-m11-ven-—-ventas-presupuestos-y-punto-de-venta" tabindex="-1">Casos de prueba de aceptación — M11 VEN — Ventas, presupuestos y punto de venta <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-m11-ven-—-ventas-presupuestos-y-punto-de-venta" aria-label="Permalink to &quot;Casos de prueba de aceptación — M11 VEN — Ventas, presupuestos y punto de venta&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/M11-VEN-ventas-presupuestos"><code>M11-VEN-ventas-presupuestos.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 94 CP de requisitos funcionales, 18 CP de escenarios ESC y 8 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_1-casos-por-requisito-funcional" tabindex="-1">1. Casos por requisito funcional <a class="header-anchor" href="#_1-casos-por-requisito-funcional" aria-label="Permalink to &quot;1. Casos por requisito funcional&quot;">​</a></h2><p>Precondiciones comunes de esta sección: ola indicada desplegada en <code>staging</code> o <code>sandbox</code>; tenant ficticio TEN-001 con la configuración publicada y las semillas del M11 §18; usuario con la capability que exige el RF (el caso negativo sin capability lo cubre la suite de permisos negativos, <code>07</code> §4.3). Resultado esperado: el criterio de aceptación del RF se cumple, la prueba automatizada cita el RF y el CP en su nombre, y quedan auditoría y evento cuando hay cambio persistente.</p><h3 id="_1-1-conceptos-por-cobrar-en-operaciones-con-titulares-piloto-m11-§5-1" tabindex="-1">1.1 Conceptos por cobrar en operaciones con titulares (piloto) (M11 §5.1) <a class="header-anchor" href="#_1-1-conceptos-por-cobrar-en-operaciones-con-titulares-piloto-m11-§5-1" aria-label="Permalink to &quot;1.1 Conceptos por cobrar en operaciones con titulares (piloto) (M11 §5.1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-VEN-0001</td><td>RF-VEN-001; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Registrar cargos por operación con titulares: derecho de conexión, instalación, reconexión, cambio de titular, traslado de domicilio, visita adicional u otro concepto habilitado por el tenant, asociados a cuenta, titular, contrato y…</td><td>Un cargo siempre tiene <code>accountId</code>, <code>contractId</code>, <code>serviceCode</code>, <code>conceptId</code> y origen; sin contrato no se admite salvo concepto marcado <code>allowWithoutContract</code>.</td></tr><tr><td>CP-VEN-0002</td><td>RF-VEN-002; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Generar el cargo automáticamente desde el hito disparador configurado por concepto (aprobación de la solicitud, OT confirmada, instalación probada, inicio de período), consumiendo eventos de M09, M10 y M08; también alta manual con permiso.</td><td>Al confirmar una OT de instalación con el concepto INS-INT configurado se crea un único cargo en estado <code>pending</code>.</td></tr><tr><td>CP-VEN-0003</td><td>RF-VEN-003; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Valorizar el cargo con el concepto y la versión tarifaria de M04 vigente a la fecha del hito, guardando la instantánea (precio, versión, regla de redondeo, tratamiento fiscal).</td><td>Cambiar la tarifa después del hito no modifica el cargo ya valorizado.</td></tr><tr><td>CP-VEN-0004</td><td>RF-VEN-004; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>integración</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Idempotencia: un mismo hito (<code>sourceType</code> + <code>sourceId</code> + <code>conceptId</code>) genera un único cargo aunque el evento llegue repetido o la app de campo sincronice dos veces.</td><td>Reprocesar el evento devuelve el cargo existente; no hay duplicado.</td></tr><tr><td>CP-VEN-0005</td><td>RF-VEN-005; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de…</td><td>Elegir la modalidad de cobro del cargo: (a) contado en la próxima factura del servicio; (b) factura inmediata propia; (c) financiado en cuotas con plan comercial, mostrando capital, interés y tributos de cada cuota.</td><td>El ejemplo de §72 (ARS 20.000 en 2 cuotas de ARS 11.000 = 10.000 de capital + 1.000 de interés) se reproduce exactamente.</td></tr><tr><td>CP-VEN-0006</td><td>RF-VEN-006; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Al elegir la financiación de un cargo se anula la alternativa de cobrarlo al contado: un solo cronograma y ninguna duplicación entre módulos.</td><td>Un cargo financiado no aparece como ítem contado en la factura del ciclo.</td></tr><tr><td>CP-VEN-0007</td><td>RF-VEN-007; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Incluir el cargo o sus cuotas en la factura periódica del servicio <strong>solo</strong> cuando el concepto está marcado como vinculado a ese servicio (<code>linkedToServiceCode</code>) y tiene validación fiscal registrada por el tenant; si no, se emite en…</td><td>Un concepto no vinculado nunca se agrega a la factura del servicio, aunque el tenant use grupos de facturación.</td></tr><tr><td>CP-VEN-0008</td><td>RF-VEN-008; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Bonificar total o parcialmente, o anular, un cargo antes de facturarlo, con motivo y aprobación por monto (T11). Después de facturado, la corrección es una NC en M05.</td><td>La bonificación queda auditada y el cargo conserva su importe original y el bonificado.</td></tr><tr><td>CP-VEN-0009</td><td>RF-VEN-009; M11 §5.1; PRO-O6-04</td><td>O6</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Generar cargos y créditos de reconexión a pedido de M08/M10: débito al reconectar un servicio no facturado en el período (P2661), crédito por días de servicio desconectado con su concepto (P2483/P2485) y opción de cerrar la OT de…</td><td>Con P2661 activo, la reconexión genera un único cargo; con P2907 la OT puede cerrarse sin cargo y queda la marca.</td></tr><tr><td>CP-VEN-0010</td><td>RF-VEN-010; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Mostrar al socio, en la PWA y en el resumen, cada cargo por operación con su origen, estado, modalidad y cronograma de cuotas.</td><td>El socio ve &quot;Instalación Internet — 2 cuotas de ARS 11.000 — cuota 1 facturada&quot;.</td></tr><tr><td>CP-VEN-0011</td><td>RF-VEN-011; M11 §5.1; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Proveer a M04/M05 los cargos pendientes para la simulación del primer cobro (abono prorrateado + instalación) antes de confirmar la contratación.</td><td>La simulación del CU-INS-01 muestra ARS 30.500 (con prorrateo y promoción) y ARS 35.000 (sin prorrateo).</td></tr><tr><td>CP-VEN-0012</td><td>RF-VEN-012; M11 §5.1; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Configurar el método de facturación de presupuestos de factibilidad: factura manual o venta de materiales.</td><td>Con &quot;venta de materiales&quot; el presupuesto de factibilidad aceptado genera una venta con sus ítems.</td></tr><tr><td>CP-VEN-0013</td><td>RF-VEN-013; M11 §5.1; PRO-O7-09</td><td>O7</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Permitir cargos por operación sobre servicios de cualquier tipo (electricidad, agua, gas, TIC, sociales) con el mismo modelo.</td><td>Un cargo de conexión de agua se registra igual que el de Internet.</td></tr></tbody></table><h3 id="_1-2-presupuestos-m11-§5-2" tabindex="-1">1.2 Presupuestos (M11 §5.2) <a class="header-anchor" href="#_1-2-presupuestos-m11-§5-2" aria-label="Permalink to &quot;1.2 Presupuestos (M11 §5.2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-VEN-0020</td><td>RF-VEN-020; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Crear presupuestos para una cuenta/titular (con persona), para una persona registrada o para un prospecto (nombre y contacto), con persona por defecto configurable (P2894); cabecera: número, fecha, validez, punto de venta, vendedor…</td><td>El presupuesto se numera por tenant y punto de venta sin huecos.</td></tr><tr><td>CP-VEN-0021</td><td>RF-VEN-021; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>migración</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Ítems de presupuesto: producto, concepto o servicio adicional; descripción (hasta el largo configurable, ProCoop trunca a 60); cantidad; precio unitario sin IVA o con IVA (P2915); descuento; alícuota; cantidad pendiente; serie reservada…</td><td>La cantidad pendiente inicia igual a la cantidad y baja al facturar o entregar.</td></tr><tr><td>CP-VEN-0022</td><td>RF-VEN-022; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Administrar el catálogo de <strong>condiciones de venta</strong> de presupuestos y seleccionarlas en cada presupuesto.</td><td>Una condición inactiva no se ofrece en presupuestos nuevos pero se conserva en los históricos.</td></tr><tr><td>CP-VEN-0023</td><td>RF-VEN-023; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Registrar <strong>notas</strong> de presupuesto con título, texto, fecha y usuario; listarlas e imprimirlas.</td><td>Las notas no se editan después de enviada la versión; se agregan nuevas.</td></tr><tr><td>CP-VEN-0024</td><td>RF-VEN-024; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td><strong>Conjuntos</strong>: agrupar ítems en conjuntos con descripción y cantidad; copiar/clonar conjunto; editar y eliminar conjunto e ítems; autocompletar el nombre del conjunto (P3004); emitir el presupuesto por conjuntos (P2949).</td><td>El total del conjunto = Σ ítems × cantidad del conjunto.</td></tr><tr><td>CP-VEN-0025</td><td>RF-VEN-025; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Precio de productos con estructura (lista de materiales de M13): costo = costo de componentes + costo fijo de fabricación; venta = costo × (1 + margen); margen por defecto (P2903) y cálculo de rentabilidad por ítem, conjunto y total.</td><td>Con costo 1.000 y margen 30 % el precio sugerido es 1.300.</td></tr><tr><td>CP-VEN-0026</td><td>RF-VEN-026; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Prorratear el importe de <strong>flete</strong> (producto P2953), <strong>molde</strong> (P3032) y de los ítems marcados &quot;prorratear&quot; entre los demás ítems en proporción al peso.</td><td>La suma prorrateada iguala exactamente el importe a repartir (residuo asignado al último ítem).</td></tr><tr><td>CP-VEN-0027</td><td>RF-VEN-027; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</td><td>Actualizar precios del presupuesto (P2892) por precio vigente, índice, cotización del dólar o margen antes de enviarlo.</td><td>La actualización crea una nueva versión si el presupuesto ya fue enviado.</td></tr><tr><td>CP-VEN-0028</td><td>RF-VEN-028; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</td><td>Validar al presupuestar, según configuración: que la cuenta tenga servicios activos (P2395; condición conectado); que el servicio no esté desconectado (con opción de cerrar si tiene deuda, P3009); que la cuenta tenga la propiedad requerida…</td><td>Cada validación puede ser bloqueante o advertencia; el override exige <code>ven.riesgo.override</code> y queda auditado.</td></tr><tr><td>CP-VEN-0029</td><td>RF-VEN-029; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</td><td>Impedir otro presupuesto vigente, no anulado y sin facturar de la misma cuenta con alguno de los mismos productos.</td><td>Se informa el presupuesto existente y su enlace.</td></tr><tr><td>CP-VEN-0030</td><td>RF-VEN-030; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Gestionar el ciclo de vida del presupuesto con transiciones explícitas (sección 8): enviar, reenviar, aprobar/aceptar, volver a borrador, rechazar, marcar para facturar, facturar parcial/total, anular, vencer.</td><td>Ninguna transición se ejecuta desde un estado no permitido (corrige <code>AprobarPresupuesto</code> sin validar estado).</td></tr><tr><td>CP-VEN-0031</td><td>RF-VEN-031; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Enviar el presupuesto por email, WhatsApp o portal con PDF de plantilla configurable (P210), impresión simple por defecto (P3037) y página extra con datos de producto (P3024); impresión masiva de presupuestos/órdenes.</td><td>El envío registra canal, destinatario, versión y resultado de entrega.</td></tr><tr><td>CP-VEN-0032</td><td>RF-VEN-032; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Regla: DSC-01: 5 % de descuento en ART-CAB-01 con pago contado y sin deuda vencida &gt; 30 días</td><td><strong>Aceptación online</strong>: el destinatario acepta o rechaza (con motivo) una versión exacta desde la PWA (si es socio autenticado) o desde un enlace firmado con verificación por OTP al contacto registrado; se guarda evidencia (versión, hash…</td><td>Aceptar una versión reemplazada o vencida es imposible; la evidencia queda en el expediente.</td></tr><tr><td>CP-VEN-0033</td><td>RF-VEN-033; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</td><td>Vencimiento automático: un presupuesto enviado cuya validez es anterior a hoy pasa a <code>expired</code> (job diario); puede renovarse creando una nueva versión con precios actualizados.</td><td>El listado distingue enviados vigentes y vencidos.</td></tr><tr><td>CP-VEN-0034</td><td>RF-VEN-034; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</td><td>Modificar un presupuesto enviado lo vuelve a borrador en una nueva versión; el cambio de cuenta/persona solo se permite antes de aprobar y con P3010.</td><td>La versión anterior queda consultable y no aceptable.</td></tr><tr><td>CP-VEN-0035</td><td>RF-VEN-035; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Aprobar un presupuesto sin obra u OT asignada pide confirmación explícita cuando P2914 está activo.</td><td>La confirmación queda registrada con el usuario.</td></tr><tr><td>CP-VEN-0036</td><td>RF-VEN-036; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Al aceptarse, ofrecer o crear automáticamente (según configuración) el caso CRM y la OT en M10 con los ítems de mano de obra y materiales, dejando el vínculo presupuesto ↔ caso ↔ OT; al rechazar o anular, desvincular y cerrar el caso.</td><td>El caso nace con tipo y estado configurables (no fijos) y asunto = referencia o número.</td></tr><tr><td>CP-VEN-0037</td><td>RF-VEN-037; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>integración</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Presupuestos en campo: enviar presupuestos a la app de campo (P2380), sincronizarlos con ventas (P2386), usar solo productos habilitados para campo, punto de venta fijo de campo (P2383), presupuestos a granel con coeficiente multiplicador…</td><td>Un producto no habilitado para campo no puede agregarse a un presupuesto que se envía a campo.</td></tr><tr><td>CP-VEN-0038</td><td>RF-VEN-038; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>integración</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Facturar en campo ventas con o sin presupuesto usando el tipo de factura configurado (P2592 / P2641), días de vencimiento (P2593), guardado del PDF (P2589), publicación del comprobante en la autogestión (VAR_PMOVIL 52) y mensaje automático…</td><td>La venta en campo offline usa <code>clientMutationId</code> y no se duplica al sincronizar.</td></tr><tr><td>CP-VEN-0039</td><td>RF-VEN-039; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Registrar anticipos sobre un presupuesto (cobro por M07) y aplicarlos al facturar; un presupuesto con anticipo no se anula sin devolver o reasignar el anticipo.</td><td>El anticipo aplicado reduce el saldo de la factura generada.</td></tr><tr><td>CP-VEN-0040</td><td>RF-VEN-040; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Generar desde el presupuesto, total o parcialmente por ítems pendientes, la venta (<code>salesOrder</code>) y/o la solicitud de factura a M05; registrar los comprobantes generados en el presupuesto.</td><td>Dos facturaciones parciales no superan la cantidad presupuestada.</td></tr><tr><td>CP-VEN-0041</td><td>RF-VEN-041; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Comprometer stock por presupuestos aprobados con obra (reserva en M13) y liberar al anular, rechazar o facturar.</td><td>El disponible de M13 descuenta lo comprometido.</td></tr><tr><td>CP-VEN-0042</td><td>RF-VEN-042; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</td><td>Alertar en la ficha de atención (M09) cuando la cuenta tiene un presupuesto pendiente (P2398).</td><td>La alerta muestra número, estado y vencimiento.</td></tr><tr><td>CP-VEN-0043</td><td>RF-VEN-043; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Permitir importar los productos de un presupuesto en un vale de materiales de M13 (P2899).</td><td>El vale referencia el presupuesto.</td></tr><tr><td>CP-VEN-0044</td><td>RF-VEN-044; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</td><td>Seleccionar un presupuesto existente desde otras pantallas (búsqueda por cuenta, número, estado) y vincularlo a obra (<code>ObtenerObras</code>) o a orden.</td><td>La búsqueda respeta el alcance de datos.</td></tr><tr><td>CP-VEN-0045</td><td>RF-VEN-045; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Cambiar el estado manualmente con permiso especial y motivo (reemplaza <code>frmPresupu_EstadoManual</code>), limitado a las transiciones de la sección 8.</td><td>El cambio manual queda en el historial con motivo.</td></tr><tr><td>CP-VEN-0046</td><td>RF-VEN-046; M11 §5.2; PRO-O8-12</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Informe de presupuestos por estado, vendedor, período, cuenta, con notas, pendientes, conversión y tiempo a aceptación.</td><td>La tasa de conversión = aceptados / enviados del período.</td></tr><tr><td>CP-VEN-0047</td><td>RF-VEN-047; M11 §5.2; PRO-O10-10</td><td>O10</td><td>Estándar</td><td>regla</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Presupuesto de obras y contribución por mejoras (MER-009): el presupuesto puede vincularse a una obra de M10 para su costeo; el prorrateo entre beneficiarios pertenece a M10/M08.</td><td>El presupuesto aceptado aporta el monto aprobado a la obra.</td></tr></tbody></table><h3 id="_1-3-venta-de-productos-entregas-y-devoluciones-m11-§5-3" tabindex="-1">1.3 Venta de productos, entregas y devoluciones (M11 §5.3) <a class="header-anchor" href="#_1-3-venta-de-productos-entregas-y-devoluciones-m11-§5-3" aria-label="Permalink to &quot;1.3 Venta de productos, entregas y devoluciones (M11 §5.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-VEN-0050</td><td>RF-VEN-050; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Registrar ventas de productos y servicios adicionales con cabecera (cuenta/titular, servicio opcional, vendedor, condición y forma de pago, lote, descuento, moneda/cotización, observaciones y transporte) e ítems (producto, cantidad, precio…</td><td>La venta confirmada solicita a M05 el comprobante y guarda su referencia.</td></tr><tr><td>CP-VEN-0051</td><td>RF-VEN-051; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</td><td>Administrar listas de precios de venta de artículos con vigencia, moneda y canal (mostrador, campo, portal), sin afectar las tarifas de servicios de M04.</td><td>Una venta toma la lista vigente a su fecha y guarda el precio aplicado.</td></tr><tr><td>CP-VEN-0052</td><td>RF-VEN-052; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Regla: DSC-01: 5 % de descuento en ART-CAB-01 con pago contado y sin deuda vencida &gt; 30 días</td><td>Reglas de recargo o descuento por producto: aplican si la cuenta tiene la propiedad y valor exigidos, coincide el tipo de titular (activo/no activo) y la forma de pago, no tiene deuda de comprobantes excluidos (o ninguna vencida hace más…</td><td>Superada la cantidad mensual la regla deja de aplicar y se informa por qué.</td></tr><tr><td>CP-VEN-0053</td><td>RF-VEN-053; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Actualización masiva de precios de venta por filtros (rango de código, departamento, rubro, tipo, servicio, proveedor, plan/etapa de vivienda) y modos porcentaje, coeficiente, cotización del dólar (precio × cotización nueva / cotización…</td><td>La previsualización muestra precio actual, nuevo y variación antes de confirmar.</td></tr><tr><td>CP-VEN-0054</td><td>RF-VEN-054; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Controlar disponibilidad y reservar stock en M13 al confirmar la venta; egresar al entregar o al confirmar según configuración (P77).</td><td>Sin disponible, la venta queda pendiente o se bloquea según configuración.</td></tr><tr><td>CP-VEN-0055</td><td>RF-VEN-055; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Entregas parciales y consulta de &quot;vendido/facturado no entregado&quot;; cada entrega registra cantidades, series, depósito, receptor, fecha y comprobante de entrega.</td><td>La venta pasa a <code>delivered</code> solo cuando no quedan pendientes.</td></tr><tr><td>CP-VEN-0056</td><td>RF-VEN-056; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Artículos: ART-ROU-01 Router Wi-Fi ARS 90.000 (serializado, 5 unidades en depósito DEP-01); ART-CAB-01 Cable UTP por metro ARS 800; ART-CON-01 Conector RJ45 ARS…</td><td>Validar trazabilidad y ubicación: un ítem de producto serializado exige una serie disponible en stock y no asignada a un suministro.</td><td>Una serie instalada en un servicio no puede venderse.</td></tr><tr><td>CP-VEN-0057</td><td>RF-VEN-057; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Regla: DSC-01: 5 % de descuento en ART-CAB-01 con pago contado y sin deuda vencida &gt; 30 días</td><td>Mostrar y validar el riesgo crediticio (deuda vencida, importe y límite) antes de financiar o vender a crédito.</td><td>Superado el límite se exige override con permiso.</td></tr><tr><td>CP-VEN-0058</td><td>RF-VEN-058; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Formas de pago de la venta: contado (con descuento contado o 1 cuota, P2247, y descuento por efectivo), cuotas según plan (entrega inicial, cantidad, máximo por cuota, interés P2089, sellado P676, días de vencimiento), crédito fiscal en…</td><td>El cronograma suma exactamente capital + interés + tributos de la operación.</td></tr><tr><td>CP-VEN-0059</td><td>RF-VEN-059; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Solicitar a M05 el comprobante fiscal de la venta: contado inmediato (esperando CAE antes de entregar si P727), venta en cuotas según el modelo fiscal configurado (factura total con concepto &quot;factura en cuotas&quot; P403 o factura por cuota).</td><td>Una venta no se entrega como &quot;facturada&quot; mientras su comprobante no tenga CAE, si P727 está activo. Según DEC-018 la espera tiene un tiempo máximo (lo fija M05); vencido, M05 emite con CAEA de contingencia o deja el comprobante pendiente, que no se entrega como fiscal.</td></tr><tr><td>CP-VEN-0060</td><td>RF-VEN-060; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Emitir siempre recibo oficial en las operaciones de caja de la venta (P2452).</td><td>El cobro en POS genera recibo de M07.</td></tr><tr><td>CP-VEN-0061</td><td>RF-VEN-061; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Registrar la diferencia de cotización en ventas en moneda extranjera como ítem con el producto configurado (P2289).</td><td>La diferencia se informa separada del precio.</td></tr><tr><td>CP-VEN-0062</td><td>RF-VEN-062; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Anular ventas individualmente o por rango (tipo, punto de venta, número desde/hasta) con permiso y respetando el cierre de ventas (P67); si el comprobante fiscal tiene CAE, la anulación se hace por NC de M05.</td><td>No se anula una venta con fecha ≤ cierre de ventas.</td></tr><tr><td>CP-VEN-0063</td><td>RF-VEN-063; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de…</td><td>Devoluciones: reingreso a stock (M13), NC (M05) y ajuste de cuotas según su estado de cobro (no facturadas se anulan; facturadas impagas se acreditan; cobradas generan saldo a favor o devolución por M07).</td><td>El CU-23 con devolución deja cuotas y saldo conciliados.</td></tr><tr><td>CP-VEN-0064</td><td>RF-VEN-064; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Venta rápida (mostrador): cuenta por defecto (P1007), vendedor por defecto (P1008) con opción de saltear su validación (P3053), impedir modificar el tipo de cuota (P2678).</td><td>La venta rápida se completa en una sola pantalla.</td></tr><tr><td>CP-VEN-0065</td><td>RF-VEN-065; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Imprimir la liquidación de crédito (P312, P2272) y la factura desde la venta (P2273); mostrar u ocultar importes por ítem en el reporte de la venta (P2246).</td><td>La liquidación de crédito informa capital, interés, CFT y cronograma.</td></tr><tr><td>CP-VEN-0066</td><td>RF-VEN-066; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Registrar los equipos o máquinas vendidos (serie, producto, fecha de compra y de entrega, precio, cliente) vinculando la venta con la ficha del activo serializado de M13; las máquinas en reparación pertenecen a M13 (RMA/servicio técnico).</td><td>Desde la venta se navega a la ficha del equipo y viceversa.</td></tr><tr><td>CP-VEN-0067</td><td>RF-VEN-067; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Vincular ventas con órdenes técnicas: los materiales vendidos en una OT generan una venta vinculada a la OT y a su solicitud.</td><td>La OT muestra sus ventas y la venta su OT.</td></tr><tr><td>CP-VEN-0068</td><td>RF-VEN-068; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>La venta de productos no exige pertenecer a un grupo de facturación (P2519): se emite en documento propio, salvo la excepción de RF-VEN-007.</td><td>Ninguna venta de producto se agrega sola a la factura del servicio.</td></tr><tr><td>CP-VEN-0069</td><td>RF-VEN-069; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Concepto de descuento en ventas y facturas (P2564) configurable.</td><td>El descuento global se informa como ítem con su concepto.</td></tr><tr><td>CP-VEN-0070</td><td>RF-VEN-070; M11 §5.3; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Artículos: ART-ROU-01 Router Wi-Fi ARS 90.000 (serializado, 5 unidades en depósito DEP-01); ART-CAB-01 Cable UTP por metro ARS 800; ART-CON-01 Conector RJ45 ARS…</td><td>Ventas de servicios adicionales (artículos y servicios adicionales) administrados como productos del catálogo de M02 marcados vendibles por canal (equivale a <code>PROD_SERV</code> 1, 2, 3, 5 u otro).</td><td>Un producto &quot;solo compras y stock&quot; no aparece en ventas.</td></tr></tbody></table><h3 id="_1-4-financiacion-comercial-y-cuotas-m11-§5-4" tabindex="-1">1.4 Financiación comercial y cuotas (M11 §5.4) <a class="header-anchor" href="#_1-4-financiacion-comercial-y-cuotas-m11-§5-4" aria-label="Permalink to &quot;1.4 Financiación comercial y cuotas (M11 §5.4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-VEN-0080</td><td>RF-VEN-080; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de…</td><td>Configurar planes de financiación comercial: cantidad de cuotas, anticipo mínimo, tasa y método (sin interés, francés, directo), sellado, máximo por cuota, periodicidad, tipo de cuota y vigencia.</td><td>El plan &quot;3 cuotas sin interés&quot; del CU-23 se configura sin código.</td></tr><tr><td>CP-VEN-0081</td><td>RF-VEN-081; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Generar el cronograma de cuotas con capital, interés, IVA (general y sobretasa), percepciones por cuota (IIBB solo si la base supera el mínimo), vencimientos y número de cuota.</td><td>La suma de cuotas = total financiado sin diferencias de redondeo.</td></tr><tr><td>CP-VEN-0082</td><td>RF-VEN-082; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de…</td><td>Mostrar simulación del plan con anticipo, cuotas, tasa nominal, TEA y costo financiero total (CFT) antes de confirmar.</td><td>La simulación coincide con el cronograma generado.</td></tr><tr><td>CP-VEN-0083</td><td>RF-VEN-083; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Estados de cuota: programada, facturada, cobrada parcial, cobrada, cancelada anticipadamente, anulada; el estado de cobro proviene de la imputación de M07.</td><td>Una cuota cobrada en caja aparece como cobrada al confirmar la imputación.</td></tr><tr><td>CP-VEN-0084</td><td>RF-VEN-084; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Facturar cuotas: por defecto en documento propio por corrida (job M05) presentado en el resumen; inclusión en la factura del servicio solo si el concepto es vinculado (RF-VEN-007).</td><td>Una cuota de venta de router nunca viaja dentro de la factura de Internet salvo que su concepto esté vinculado y validado.</td></tr><tr><td>CP-VEN-0085</td><td>RF-VEN-085; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Cuando la inclusión está permitida, agrupar las cuotas: las asociadas a un servicio van con ese servicio y su grupo de facturación; las de un tipo de cuota con grupo indicado, al grupo indicado; el resto, al grupo por defecto.</td><td>La factura de un grupo contiene solo cuotas de servicios del grupo.</td></tr><tr><td>CP-VEN-0086</td><td>RF-VEN-086; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Estándar</td><td>regla</td><td>TEN-001 con Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</td><td>Seleccionar cuotas a facturar por rango de vencimiento (hasta una fecha, sin tomar las anteriores a &quot;desde − N meses&quot;, N = 10 configurable) o lista explícita; incluir intereses diferidos si se pide.</td><td>Una cuota ya facturada (con factura) no se vuelve a tomar.</td></tr><tr><td>CP-VEN-0087</td><td>RF-VEN-087; M11 §5.4; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de…</td><td>Cancelación anticipada total o parcial con quita del interés no devengado según la condición del plan, generando el ajuste o NC correspondiente.</td><td>La cancelación de 2 cuotas restantes descuenta sus intereses futuros.</td></tr><tr><td>CP-VEN-0088</td><td>RF-VEN-088; M11 §5.4; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>migración</td><td>TEN-001 con Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de…</td><td>Modificación masiva de cuotas pendientes (sin factura, no anuladas): importe de un producto por porcentaje repartido proporcional a capital, costo del producto (diferencia contra el último precio usado), desplazar vencimientos N meses…</td><td>La sobretasa usa su propia tasa (corrige el defecto de ProCoop).</td></tr><tr><td>CP-VEN-0089</td><td>RF-VEN-089; M11 §5.4; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Anticipos de productos: concepto de anticipo (P29), tipo de cuota para anticipo de productos (P2409), opción de descontarlos de facturación futura (P3008) y de usarlos en la facturación masiva (P3038).</td><td>Un anticipo de producto aplicado en la masiva no se aplica dos veces.</td></tr><tr><td>CP-VEN-0090</td><td>RF-VEN-090; M11 §5.4; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Informar a M06 los ítems financiados para separarlos en el libro IVA ventas (P2972) y el detalle de ventas con concepto &quot;factura en cuotas&quot; (P403) como exento o excluido.</td><td>El libro IVA de M06 muestra los financiados separados si P2972.</td></tr><tr><td>CP-VEN-0091</td><td>RF-VEN-091; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Distinguir siempre la financiación de una venta nueva de la regularización de deuda anterior (M08): distinto tipo de operación, numeración, reportes y reglas, aunque compartan el componente de cronograma.</td><td>Un convenio de M08 no puede incluir como &quot;venta&quot; una deuda anterior ni viceversa.</td></tr><tr><td>CP-VEN-0092</td><td>RF-VEN-092; M11 §5.4; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Relacionar cada cuota y cada factura con su operación original (cargo, venta o presupuesto).</td><td>Desde la cuota se navega a la venta y desde la venta a todas sus cuotas y facturas.</td></tr><tr><td>CP-VEN-0093</td><td>RF-VEN-093; M11 §5.4; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>migración</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Recibir de M05 las importaciones de terceros con destino &quot;venta con cuotas&quot; (formatos EMA, SAM, EME, CT1, FAR, IAL, CEL) y crear las ventas y cuotas con numeración sin huecos.</td><td>Una importación no deja números sin usar (corrige el defecto de ProCoop).</td></tr><tr><td>CP-VEN-0094</td><td>RF-VEN-094; M11 §5.4; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</td><td>Consultar el detalle de cuotas de una cuenta y agregar deuda en cuotas desde la cobranza (equivalente a <code>frmDetallecuotas</code>, <code>frmAgregarDeudaCuotas</code>), sin reconstruir cuotas por fuera de las reglas.</td><td>La reconstrucción de cuotas (<code>frmReconstruccion_Cuotas</code>) se reemplaza por la auditoría del cronograma.</td></tr></tbody></table><h3 id="_1-5-vendedores-pos-y-rendiciones-m11-§5-5" tabindex="-1">1.5 Vendedores, POS y rendiciones (M11 §5.5) <a class="header-anchor" href="#_1-5-vendedores-pos-y-rendiciones-m11-§5-5" aria-label="Permalink to &quot;1.5 Vendedores, POS y rendiciones (M11 §5.5)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-VEN-0100</td><td>RF-VEN-100; M11 §5.5; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Vendedores: VND-01 &quot;Vendedor Demo Uno&quot; (sucursal central); VND-02 &quot;Vendedor Demo Dos&quot;</td><td>ABM de vendedores: nombre o razón social, domicilio (calle, número, departamento, piso, barrio, provincia, localidad, código postal), teléfono, fax, celular, email, vínculo opcional con usuario o empleado (M16), sucursal, activo/inactivo.</td><td>Un vendedor inactivo no se asigna a operaciones nuevas.</td></tr><tr><td>CP-VEN-0101</td><td>RF-VEN-101; M11 §5.5; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>migración</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Vendedor por defecto por canal: venta rápida (P1008), anticipos y notificaciones de M07/M08 que ProCoop atribuye a un vendedor, redondeo de cobranza en efectivo (P3069); el vendedor es opcional salvo configuración.</td><td>Sin vendedor y con la validación activa, la venta no se confirma.</td></tr><tr><td>CP-VEN-0102</td><td>RF-VEN-102; M11 §5.5; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Informe de ventas y presupuestos por vendedor (cantidad, importe, conversión, devoluciones).</td><td>El informe concilia con el total de ventas del período.</td></tr><tr><td>CP-VEN-0103</td><td>RF-VEN-103; M11 §5.5; PRO-O11-05</td><td>O11</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Vendedores: VND-01 &quot;Vendedor Demo Uno&quot; (sucursal central); VND-02 &quot;Vendedor Demo Dos&quot;</td><td>Comisiones de vendedores.</td><td>Solo si se aprueba PA-VEN-03.</td></tr><tr><td>CP-VEN-0104</td><td>RF-VEN-104; M11 §5.5; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</td><td>POS de mostrador por sucursal: terminal configurada (punto de venta fiscal de M05, depósito, lista de precios, caja de M07), apertura y cierre de sesión con arqueo, venta rápida con lector de código de barras, cobro con varios medios…</td><td>Un cierre de sesión cuadra ventas, cobros por medio y comprobantes emitidos.</td></tr><tr><td>CP-VEN-0105</td><td>RF-VEN-105; M11 §5.5; PRO-O10-10</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</td><td>Impresión de tickets y uso de lector/impresora de mostrador mediante el agente local de hardware.</td><td>Sin agente, el ticket se imprime desde el navegador.</td></tr><tr><td>CP-VEN-0106</td><td>RF-VEN-106; M11 §5.5; PRO-O4-13</td><td>O4</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>La numeración por punto de venta y comprobante (<code>COMPPOS</code>) es de M05; los descuentos por servicio y categoría (<code>DESCPOS</code>) son de M04; las posiciones de regleta telefónica (<code>TEL_POS_REG_*</code>) son de M10.</td><td>Ver CTR-VEN-02.</td></tr><tr><td>CP-VEN-0107</td><td>RF-VEN-107; M11 §5.5; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Rendición de viajes de una venta: km reales, flete real, tipo de flete (sin asignar, propio, tercero — valores distintos), peajes, viáticos e ítems de combustible (puesto, comprobante, litros, precio por litro, cargado en viaje); cálculo…</td><td>El informe de rendición no confunde transporte propio con sin asignar.</td></tr><tr><td>CP-VEN-0108</td><td>RF-VEN-108; M11 §5.5; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Rendición de comprobantes de venta según cobranzas (P76) <strong>[VERIFICAR]</strong> su significado con una cooperativa que la tenga activa.</td><td>Sin confirmación, no se implementa.</td></tr></tbody></table><h3 id="_1-6-flujo-continuo-transversales-y-reportes-m11-§5-6" tabindex="-1">1.6 Flujo continuo, transversales y reportes (M11 §5.6) <a class="header-anchor" href="#_1-6-flujo-continuo-transversales-y-reportes-m11-§5-6" aria-label="Permalink to &quot;1.6 Flujo continuo, transversales y reportes (M11 §5.6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-VEN-0110</td><td>RF-VEN-110; M11 §5.6; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Flujo continuo <strong>presupuesto → aceptación online → OT → consumo de materiales → venta/factura</strong> en un único expediente (T11) con línea de tiempo, sin recarga manual de datos entre etapas.</td><td>Al cerrar la OT, los materiales consumidos se comparan con lo presupuestado y la factura se genera con lo aceptado más las diferencias aprobadas.</td></tr><tr><td>CP-VEN-0111</td><td>RF-VEN-111; M11 §5.6; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador…</td><td>Diferencias entre lo presupuestado y lo ejecutado en la OT (más o menos materiales/horas): se facturan según la condición aceptada (precio cerrado o a liquidar) y las diferencias por encima de la tolerancia requieren aprobación del cliente…</td><td>Con precio cerrado, un consumo mayor no aumenta la factura.</td></tr><tr><td>CP-VEN-0112</td><td>RF-VEN-112; M11 §5.6; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Tablero kanban de presupuestos y ventas por estado, con filtros por vendedor, sucursal y servicio.</td><td>Arrastrar una tarjeta ejecuta solo transiciones permitidas.</td></tr><tr><td>CP-VEN-0113</td><td>RF-VEN-113; M11 §5.6; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Notificar al socio cada cambio de estado relevante (presupuesto enviado, por vencer, aceptado, OT programada, factura emitida, cuota por vencer) vía T09.</td><td>El socio recibe la notificación en el canal preferido.</td></tr><tr><td>CP-VEN-0114</td><td>RF-VEN-114; M11 §5.6; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>funcional</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Respetar el cierre de período de ventas (P67) y de facturación mediante la entidad unificada de períodos de T04/M15.</td><td>Una operación con fecha en período cerrado se rechaza con mensaje claro.</td></tr><tr><td>CP-VEN-0115</td><td>RF-VEN-115; M11 §5.6; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 con Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</td><td>Reportes de ventas de productos (por producto, rubro, servicio, sucursal, vendedor, forma de pago), detalle de ventas, cuotas facturadas y pendientes, comprobantes no facturados, cargos por operación pendientes y facturados, conversión de…</td><td>Cada reporte declara fórmula, universo y fecha de corte.</td></tr><tr><td>CP-VEN-0116</td><td>RF-VEN-116; M11 §5.6; PRO-O4-13</td><td>O4</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 con Presupuestos: PRE-0001-00000001 (borrador), PRE-0001-00000002 (enviado), PRE-0001-00000003 (aceptado con OT), PRE-0001-00000004 (vencido)</td><td>Todas las etiquetas por diccionario del tenant; documentos con plantillas del tenant; auditoría de cada cambio; aislamiento por tenant en consultas, exportaciones y APIs.</td><td>Un usuario de TEN-002 no ve presupuestos de TEN-001 ni por API.</td></tr><tr><td>CP-VEN-0117</td><td>RF-VEN-117; M11 §5.6; PRO-O8-13</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 con Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</td><td>Copiar entre tenants la configuración de M11 (condiciones de venta, planes, reglas, plantillas) sin copiar operaciones.</td><td>La copia no incluye presupuestos, ventas ni cuotas.</td></tr></tbody></table><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-VEN-5001 — ESC-VEN-01. Instalación financiada CU-PRO-01</strong></p><ul><li>Cubre: ESC-VEN-01; relacionados: CU-PRO-01; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de ejemplo</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Instalación financiada CU-PRO-01</li><li>Entonces 1 cargo, 2 cuotas de ARS 11.000, sin ítem contado.</li></ul><p><strong>CP-VEN-5002 — ESC-VEN-02. Cuota de router (no vinculada) en ciclo de Internet</strong></p><ul><li>Cubre: ESC-VEN-02; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cuota de router (no vinculada) en ciclo de Internet</li><li>Entonces Documento propio; la factura de Internet no contiene la cuota.</li></ul><p><strong>CP-VEN-5003 — ESC-VEN-03. Concepto vinculado sin validación fiscal</strong></p><ul><li>Cubre: ESC-VEN-03; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Concepto vinculado sin validación fiscal</li><li>Entonces No se incluye; documento propio y alerta de configuración.</li></ul><p><strong>CP-VEN-5004 — ESC-VEN-04. Evento de OT duplicado</strong></p><ul><li>Cubre: ESC-VEN-04; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Evento de OT duplicado</li><li>Entonces Un solo cargo.</li></ul><p><strong>CP-VEN-5005 — ESC-VEN-05. Visita fallida</strong></p><ul><li>Cubre: ESC-VEN-05; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Visita fallida</li><li>Entonces Ningún cargo.</li></ul><p><strong>CP-VEN-5006 — ESC-VEN-06. Aceptación de versión reemplazada</strong></p><ul><li>Cubre: ESC-VEN-06; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Aceptación de versión reemplazada</li><li>Entonces Error <code>ven/quote-version-superseded</code>.</li></ul><p><strong>CP-VEN-5007 — ESC-VEN-07. Presupuesto duplicado misma cuenta y producto</strong></p><ul><li>Cubre: ESC-VEN-07; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Presupuesto duplicado misma cuenta y producto</li><li>Entonces Bloqueo con enlace al existente.</li></ul><p><strong>CP-VEN-5008 — ESC-VEN-08. Aprobar presupuesto anulado (defecto ProCoop)</strong></p><ul><li>Cubre: ESC-VEN-08; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: migración</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Aprobar presupuesto anulado (defecto ProCoop)</li><li>Entonces Error <code>ven/invalid-transition</code>.</li></ul><p><strong>CP-VEN-5009 — ESC-VEN-09. Venta de serie instalada en un suministro</strong></p><ul><li>Cubre: ESC-VEN-09; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Venta de serie instalada en un suministro</li><li>Entonces Error <code>ven/serial-not-available</code>.</li></ul><p><strong>CP-VEN-5010 — ESC-VEN-10. Riesgo excedido en modo <code>block</code></strong></p><ul><li>Cubre: ESC-VEN-10; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Riesgo excedido en modo <code>block</code></li><li>Entonces Venta en <code>pendingApproval</code>; override con permiso.</li></ul><p><strong>CP-VEN-5011 — ESC-VEN-11. Devolución CU-23 con cuota 1 cobrada</strong></p><ul><li>Cubre: ESC-VEN-11; relacionados: CU-23; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Devolución CU-23 con cuota 1 cobrada</li><li>Entonces Cuotas 2–3 anuladas; saldo a favor.</li></ul><p><strong>CP-VEN-5012 — ESC-VEN-12. Descuento contado con IVA</strong></p><ul><li>Cubre: ESC-VEN-12; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Regla: DSC-01: 5 % de descuento en ART-CAB-01 con pago contado y sin deuda vencida &gt; 30 días</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Descuento contado con IVA</li><li>Entonces IVA sobre neto con descuento.</li></ul><p><strong>CP-VEN-5013 — ESC-VEN-13. Modificación masiva de sobretasa</strong></p><ul><li>Cubre: ESC-VEN-13; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de ejemplo</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Modificación masiva de sobretasa</li><li>Entonces Usa la tasa de sobretasa, no la general.</li></ul><p><strong>CP-VEN-5014 — ESC-VEN-14. Importación de terceros con cuotas</strong></p><ul><li>Cubre: ESC-VEN-14; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de ejemplo</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Importación de terceros con cuotas</li><li>Entonces Numeración sin huecos.</li></ul><p><strong>CP-VEN-5015 — ESC-VEN-15. Rendición con transporte propio</strong></p><ul><li>Cubre: ESC-VEN-15; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Rendición con transporte propio</li><li>Entonces Valor distinto de &quot;sin asignar&quot;; precio/km = flete/km.</li></ul><p><strong>CP-VEN-5016 — ESC-VEN-16. Cierre de POS con diferencia</strong></p><ul><li>Cubre: ESC-VEN-16; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cierre de POS con diferencia</li><li>Entonces Diferencia registrada; sesión <code>closed</code> hasta conciliar.</li></ul><p><strong>CP-VEN-5017 — ESC-VEN-17. Cancelación anticipada de 2 cuotas</strong></p><ul><li>Cubre: ESC-VEN-17; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Planes: FIN-3SI &quot;3 cuotas sin interés&quot;; FIN-2INS &quot;2 cuotas instalación&quot; (tasa que da 2 × ARS 11.000 sobre ARS 20.000); FIN-6FR &quot;6 cuotas francés&quot; con TEA de ejemplo</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cancelación anticipada de 2 cuotas</li><li>Entonces Quita de interés no devengado según plan.</li></ul><p><strong>CP-VEN-5018 — ESC-VEN-18. Usuario de TEN-002 consulta presupuesto de TEN-001 por API</strong></p><ul><li>Cubre: ESC-VEN-18; M11 §17.2</li><li>Ola: O8 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001 y TEN-002; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Usuario de TEN-002 consulta presupuesto de TEN-001 por API</li><li>Entonces 404.</li></ul><h2 id="_3-casos-por-caso-de-uso-cu" tabindex="-1">3. Casos por caso de uso (CU) <a class="header-anchor" href="#_3-casos-por-caso-de-uso-cu" aria-label="Permalink to &quot;3. Casos por caso de uso (CU)&quot;">​</a></h2><p><strong>CP-VEN-8001 — CU-23. Venta de producto financiada en cuotas (BASE §23)</strong></p><ul><li>Cubre: CU-23; M11 §16</li><li>Ola: O8 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado TEN-001 con artículo ART-ROU-01 (router) en stock, precio ARS 90.000, plan &quot;3 cuotas sin interés&quot;. -; actor: vendedor; sistema: M11, M13, M05, M07. -, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando 1) el vendedor registra la venta VEN-001 a la cuenta de prueba; 2) M13 confirma disponibilidad y reserva; 3) elige el plan y ve la simulación (3 × ARS 30.000, TEA 0, CFT 0); 4) confirma; M05 emite según el modelo fiscal (PA-VEN-02); 5) entrega del equipo con serie (egreso M13); 6) las cuotas se facturan por corrida en documento propio y se presentan en el resumen; 7) M07 registra los cobros y las cuotas pasan a <code>paid</code>. - Excepción: devolución tras la cuota 1 cobrada: reingreso al depósito, NC, cuotas 2 y 3…</li><li>Entonces Venta, entrega, cuotas, facturas y cobros vinculados; ninguna cuota viaja en la factura de Internet.</li></ul><p><strong>CP-VEN-8002 — CU-PRO-01. Instalación financiada en el piloto (BASE §72)</strong></p><ul><li>Cubre: CU-PRO-01; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando contratación de Internet con instalación ARS 20.000 financiada en 2 cuotas de ARS 11.000 (10.000 de capital + 1.000 de interés cada una); al confirmar la OT nace un único cargo; se generan 2 cuotas vinculadas al servicio INT; la alternativa contado queda anulada. -</li><li>Entonces La cuota 1 viaja en la primera factura de Internet (concepto vinculado y validado) o en documento propio si el tenant no validó la inclusión.</li></ul><p><strong>CP-VEN-8003 — CU-INS-01. Primer cobro con instalación (BASE §73, compartido con M04/M05)</strong></p><ul><li>Cubre: CU-INS-01; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Ventas: VEN-001 (CU-23, 3 cuotas de ARS 30.000); VEN-002 venta POS contado</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando M11 aporta el cargo INS-INT de ARS 30.000 (contado) a la simulación; con prorrateo y promoción el primer cobro es ARS 30.500; sin prorrateo, ARS 35.000. Una visita fallida no genera cargo. Los importes son los del ejemplo de BASE §73 y valen solo para este caso; el <em>seed</em> demo usa INS-INT ARS 20.000 (M02 §18, HUE-SRV-05; ver CTR-TAR-30 de M04).</li><li>Entonces Se completa «Primer cobro con instalación (BASE §73, compartido con M04/M05)» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-VEN-8004 — CU-VEN-01. Presupuesto con aceptación online y flujo continuo</strong></p><ul><li>Cubre: CU-VEN-01; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Conceptos: INS-INT &quot;Instalación Internet&quot; ARS 20.000, valor del <em>seed</em> único de M02 §18 (HUE-SRV-05; antes ARS 30.000, de BASE §39.3) (disparador <code>installationConfirmed</code>, vinculado a INT, validación fiscal registrada); CON-INT…</li><li>Dado actor: vendedor, socio, técnico. -, autenticado en TEN-001 con las capabilities de su rol</li><li>Cuando 1) el vendedor crea un presupuesto de ampliación de red interna con un conjunto &quot;Materiales&quot; y otro &quot;Mano de obra&quot;; 2) lo envía por email con enlace; 3) el socio abre el enlace, recibe OTP y acepta la versión 1; 4) se crea el caso CRM y la OT con los materiales reservados; 5) el técnico ejecuta y reporta un 3 % más de cable (dentro de tolerancia 5 %); 6) el presupuesto pasa a <code>toInvoice</code> y se factura lo aceptado (precio cerrado); 7) el socio recibe la factura. -</li><li>Entonces Se completa «Presupuesto con aceptación online y flujo continuo» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio. Alternativo o excepción: versión vencida → el enlace informa y ofrece pedir actualización; consumo 12 % mayor → aprobación del supervisor o del socio antes de facturar la diferencia.</li></ul><p><strong>CP-VEN-8005 — CU-VEN-02. Venta en POS de mostrador</strong></p><ul><li>Cubre: CU-VEN-02; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Condiciones de venta: CND-01 &quot;Contado contra entrega&quot;; CND-02 &quot;Validez 15 días&quot;; CND-03 &quot;Garantía 6 meses&quot;</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando el cajero abre sesión con fondo ARS 10.000; vende un cable y un conector a consumidor final (cuenta por defecto); cobra con tarjeta de débito; se emite factura electrónica y ticket; al cierre, el arqueo cuadra por medio. - Excepción: sin conexión con ARCA, la venta queda pendiente de emisión y no se entrega como facturada si P727 está activo.</li><li>Entonces Se completa «Venta en POS de mostrador» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-VEN-8006 — CU-VEN-03. Reconexión con cargo (O6)</strong></p><ul><li>Cubre: CU-VEN-03; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando M08 decide reconectar una cuenta con deuda regularizada; M10 confirma la OT; M11 genera el cargo de reconexión (concepto de M04) a la próxima factura del servicio y, si P2483 está activo, un crédito por los días desconectados.</li><li>Entonces Se completa «Reconexión con cargo (O6)» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-VEN-8007 — CU-VEN-04. Modificación masiva de cuotas</strong></p><ul><li>Cubre: CU-VEN-04; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Cuenta: Cuenta de prueba &quot;Socio Demo&quot; con servicio INT activo (M01)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando el administrativo aumenta 10 % las cuotas pendientes de un producto; ve la vista previa (cantidad, importe actual, nuevo), confirma con motivo; el job actualiza, deja nota en cada cuenta y movimiento de ajuste. - Excepción: cuotas ya facturadas quedan excluidas y se informan.</li><li>Entonces Se completa «Modificación masiva de cuotas» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul><p><strong>CP-VEN-8008 — CU-VEN-05. Presupuesto en campo</strong></p><ul><li>Cubre: CU-VEN-05; M11 §16</li><li>Ola: O8 · Prioridad: Estándar · Tipo: integración</li><li>Precondiciones: ola O8 desplegada; tenant ficticio TEN-001; semillas de M11 §18.</li><li>Datos de prueba: Lista de precios: LST-MOST (mostrador), LST-CAMPO (campo)</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando el técnico, sin señal, arma un presupuesto con productos habilitados para campo, el socio firma en pantalla; al sincronizar se crea una única vez y, si se factura en campo, se usa el tipo P2592 y se publica en autogestión.</li><li>Entonces Se completa «Presupuesto en campo» sin errores, con el resultado que describe el anexo, y quedan auditoría y evento del cambio</li></ul>',72)])])}const N=e(n,[["render",i]]);export{E as __pageData,N as default};
